import{_ as a,o as t,c as n,ah as s}from"./chunks/framework.Bja9t6Wf.js";const p=JSON.parse('{"title":"Screenplay Updates: Key Scenes Translated","description":"","frontmatter":{},"headers":[],"relativePath":"en/logbuch/szene-updates.md","filePath":"en/logbuch/szene-updates.md"}'),o={name:"en/logbuch/szene-updates.md"};function r(i,e,c,l,h,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="screenplay-updates-key-scenes-translated" tabindex="-1">Screenplay Updates: Key Scenes Translated <a class="header-anchor" href="#screenplay-updates-key-scenes-translated" aria-label="Permalink to &quot;Screenplay Updates: Key Scenes Translated&quot;">​</a></h1><p>We have documented several key scenes that define the tone of the mockumentary. Here is a summary of the latest updates:</p><h3 id="scene-15-the-protocol-of-silence" tabindex="-1">Scene 15: The Protocol of Silence <a class="header-anchor" href="#scene-15-the-protocol-of-silence" aria-label="Permalink to &quot;Scene 15: The Protocol of Silence&quot;">​</a></h3><p>A dark, bureaucratic dance in the archives of Duisburg (1936). The names of the predecessors are erased with terrifying efficiency.</p><h3 id="scene-22-the-emoji-lesson" tabindex="-1">Scene 22: The Emoji Lesson <a class="header-anchor" href="#scene-22-the-emoji-lesson" aria-label="Permalink to &quot;Scene 22: The Emoji Lesson&quot;">​</a></h3><p>A modern satire. Political advisors discuss how to describe million-euro tranches in WhatsApp chats using only emojis to avoid the Court of Audit.</p><h3 id="scene-31-the-art-of-benevolence" tabindex="-1">Scene 31: The Art of Benevolence <a class="header-anchor" href="#scene-31-the-art-of-benevolence" aria-label="Permalink to &quot;Scene 31: The Art of Benevolence&quot;">​</a></h3><p>Heidi Horten explains her philosophy of &quot;Giving.&quot; Every donation is a brushstroke in her pointillist masterpiece of influence.</p><h3 id="scene-42-the-aesthetic-of-smallness" tabindex="-1">Scene 42: The Aesthetic of Smallness <a class="header-anchor" href="#scene-42-the-aesthetic-of-smallness" aria-label="Permalink to &quot;Scene 42: The Aesthetic of Smallness&quot;">​</a></h3><p>A study of tranches. Why 49,000 is more beautiful than 50,000. A lesson in mathematical invisibility.</p><h3 id="scene-50-the-eternal-window" tabindex="-1">Scene 50: The Eternal Window <a class="header-anchor" href="#scene-50-the-eternal-window" aria-label="Permalink to &quot;Scene 50: The Eternal Window&quot;">​</a></h3><p>Helmut Horten stands in front of his first &quot;acquired&quot; store. He sees not the past, but an endless future of consumption.</p><p><em>These scenes are now being integrated into the full English screenplay.</em></p>',13)])])}const f=a(o,[["render",r]]);export{p as __pageData,f as default};
